package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import org.json.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class ServerSelectionUiTest {
    WorkspaceServers servers;TermuxActivity activity;ServerProfiles.Profile profile;
    Object field(String n)throws Exception{Field f=WorkspaceServers.class.getDeclaredField(n);f.setAccessible(true);return f.get(servers);}void set(String n,Object value)throws Exception{Field f=WorkspaceServers.class.getDeclaredField(n);f.setAccessible(true);f.set(servers,value);}
    Object call(String n,Class<?>[] types,Object... args)throws Exception{Method m=WorkspaceServers.class.getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(servers,args);}
    JSONObject file(String name)throws Exception{return new JSONObject().put("name",name).put("path","/fixture/"+name).put("size",1);}
    @Before public void setup()throws Exception{activity=Robolectric.buildActivity(TermuxActivity.class).get();activity.setTheme(R.style.Theme_Termux_Black);WorkspaceLanguage.select(activity,"en");servers=new WorkspaceServers(activity,(n,c)->{throw new AssertionError("No terminal expected");});profile=new ServerProfiles.Profile();profile.name="fixture";set("selected",profile);set("directory","/fixture");set("listing",new JSONObject().put("path","/fixture").put("entries",new JSONArray().put(file("one")).put(file("two"))));call("files",new Class<?>[]{LinearLayout.class},new LinearLayout(activity));}
    @After public void close(){servers.close();}
    @Test public void longPressSelectsForPersistentDownloadAndMovePanel()throws Exception{TextView action=(TextView)field("downloadSelectedButton");assertEquals(View.VISIBLE,action.getVisibility());View row=(View)call("fileRow",new Class<?>[]{JSONObject.class},file("one"));assertTrue(row.performLongClick());assertEquals(View.VISIBLE,action.getVisibility());assertTrue(action.getContentDescription().toString().endsWith("1"));action.performClick();AlertDialog menu=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Download…",menu.getListView().getAdapter().getItem(0));assertEquals("Move…",menu.getListView().getAdapter().getItem(1));}
    @Test public void bottomPanelOffersSelectionWhenNothingWasLongPressed()throws Exception{TextView action=(TextView)field("downloadSelectedButton");action.performClick();AlertDialog menu=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Download from server…",menu.getListView().getAdapter().getItem(0));menu.getListView().performItemClick(null,0,0);AlertDialog chooser=ShadowAlertDialog.getLatestAlertDialog();assertEquals(2,chooser.getListView().getCount());assertFalse(chooser.getButton(-1).isEnabled());chooser.getListView().performItemClick(null,0,0);assertTrue(chooser.getButton(-1).isEnabled());}
    @Test public void pendingMoveSurvivesOpeningAnotherFolderAndCanBeCancelled()throws Exception{View row=(View)call("fileRow",new Class<?>[]{JSONObject.class},file("one"));row.performLongClick();((View)field("downloadSelectedButton")).performClick();AlertDialog menu=ShadowAlertDialog.getLatestAlertDialog();menu.getListView().performItemClick(null,1,1);set("listing",new JSONObject().put("path","/destination").put("entries",new JSONArray()));call("updateFileViews",new Class<?>[]{});TextView action=(TextView)field("downloadSelectedButton");assertEquals(View.VISIBLE,action.getVisibility());assertTrue(action.getContentDescription().toString().startsWith("Move here"));action.performClick();menu=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Cancel move",menu.getListView().getAdapter().getItem(1));menu.getListView().performItemClick(null,1,1);assertEquals(View.VISIBLE,action.getVisibility());assertTrue(action.getContentDescription().toString().startsWith("Download from server"));}
}
